<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $meds=db()->query('SELECT m.*,COALESCE(SUM(b.units_remaining),0) stock FROM medicines m LEFT JOIN batches b ON b.medicine_id=m.id AND (b.expiry_date IS NULL OR b.expiry_date>=CURDATE()) WHERE m.active=1 GROUP BY m.id ORDER BY m.name')->fetchAll(); $customers=db()->query('SELECT id,name,phone FROM customers ORDER BY name')->fetchAll(); function e2(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');} $saleToken=bin2hex(random_bytes(24)); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pharmacy POS · <?=e2(APP_NAME)?></title><link rel="stylesheet" href="style.css"><style>html,body{height:100%;overflow:hidden}body{margin:0}.pos-shell{height:calc(100vh - 76px);display:grid;grid-template-rows:44px minmax(0,1fr) 28px;gap:8px}.pos-top{display:flex;gap:8px;align-items:center}.pos-top input{flex:1;font-size:17px;padding:10px 14px;border-radius:10px;border:1px solid #cbd5e1}.pos-grid{min-height:0;display:grid;grid-template-columns:27% 45% 28%;gap:8px}.pos-card{min-width:0;min-height:0;background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:11px;display:flex;flex-direction:column;overflow:hidden}.pos-card h2{font-size:14px;margin:0 0 7px}.scroll{overflow:auto;min-height:0}.result{display:flex;justify-content:space-between;gap:7px;align-items:center;padding:8px 3px;border-bottom:1px solid #edf0f4}.result b{font-size:12px}.result small{display:block;color:#64748b;font-size:9px;margin-top:2px}.sell-buttons{display:flex;gap:3px;flex-shrink:0}.mini{padding:6px 7px;font-size:9px;min-width:52px}.cart-head{display:flex;justify-content:space-between;align-items:center}.cart-head span{font-size:9px;color:#64748b}.cartrow{border-bottom:1px solid #e2e8f0;padding:7px 0}.cart-main{display:grid;grid-template-columns:1fr 58px 72px 20px;gap:6px;align-items:center}.cartrow small{display:block;color:#64748b;font-size:9px;margin-top:2px}.cartrow input{width:48px;padding:5px}.item-actions{display:flex;gap:5px;align-items:center;margin-top:4px}.item-actions input{width:45px}.remove{border:0;background:transparent;color:#c53030;font-size:18px;cursor:pointer}.checkout-card{gap:6px}.field-label{font-size:9px;text-transform:uppercase;color:#64748b;font-weight:700;margin-bottom:3px}.checkout-card select,.checkout-card input{width:100%;box-sizing:border-box;padding:8px;border:1px solid #cbd5e1;border-radius:7px}.summary{border-top:1px solid #e2e8f0;padding-top:7px;margin-top:auto}.summary div{display:flex;justify-content:space-between;padding:2px 0;font-size:11px}.summary .grand{font-size:19px;font-weight:800;border-top:1px solid #e2e8f0;margin-top:3px;padding-top:6px}.pay-buttons{display:grid;grid-template-columns:repeat(3,1fr);gap:4px}.pay-buttons button{padding:7px 3px;font-size:9px}.pay-buttons .active{outline:2px solid #315fca}.change{padding:6px;border-radius:6px;background:#ecfdf5;color:#166534;font-weight:700;font-size:10px}.due{padding:6px;border-radius:6px;background:#fff7ed;color:#9a3412;font-weight:700;font-size:10px}.complete{width:100%;font-size:14px;padding:11px}.shortcuts{font-size:8px;color:#64748b;text-align:center;white-space:nowrap}.empty{text-align:center;color:#64748b;padding:30px 8px}.empty b{display:block;color:#334155;margin-bottom:4px}.holdbar{display:flex;gap:4px;padding-top:5px}.holdbar button{flex:1;padding:6px;font-size:9px}.quick-meds{display:flex;gap:4px;overflow:auto;padding-top:5px}.quick-meds button{white-space:nowrap;font-size:9px;padding:5px 7px}.status{font-size:9px;color:#166534;font-weight:700;white-space:nowrap}.modal-back{position:fixed;inset:0;background:rgba(15,23,42,.45);display:none;align-items:center;justify-content:center;z-index:100}.modal{background:#fff;border-radius:12px;padding:16px;width:min(400px,90vw)}.modal h3{margin:0 0 5px}.modal .row{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.modal input{width:100%;box-sizing:border-box;padding:9px}.modal-actions{display:flex;gap:7px;margin-top:10px}.modal-actions button{flex:1;padding:9px}@media(max-height:680px){.pos-shell{grid-template-rows:38px minmax(0,1fr) 24px}.pos-card{padding:8px}.result{padding:5px 2px}.cartrow{padding:5px 0}.checkout-card{gap:4px}.summary div{padding:1px 0}.complete{padding:8px}}@media(max-width:950px){.pos-grid{grid-template-columns:26% 44% 30%}.mini{min-width:42px;padding:5px 3px}.cart-main{grid-template-columns:1fr 50px 65px 18px}}@media print{body>*{display:none!important}}</style></head><body><header><div class="brand">💊 <?=e2(APP_NAME)?></div><nav><a href="index.php?action=dashboard">Dashboard</a><a class="active" href="pos.php">POS</a><a href="manage.php">Management</a></nav><div class="user-info">👤 <?=e2(current_user()['username']??'')?> · <?=e2(ucfirst(current_user()['role']??''))?> · <a href="logout.php">Logout</a></div></header><main class="pos-shell"><div class="pos-top"><input id="search" autocomplete="off" placeholder="🔎 Search medicine, generic, strength or scan barcode..."><span class="shortcut">F2 SEARCH</span><span class="status">● READY</span></div><div class="pos-grid"><section class="pos-card"><h2>🔎 Medicine Search</h2><div id="results" class="scroll"></div><div class="quick-meds" id="quickMeds"></div></section><section class="pos-card"><div class="cart-head"><h2>🛒 Current Sale</h2><span id="count">0 units</span></div><div id="cart" class="scroll"></div><div class="holdbar"><button type="button" onclick="holdSale()">⏸ HOLD F6</button><button type="button" onclick="resumeSale()">▶ RESUME F7</button><button type="button" onclick="clearCart()">✕ CLEAR</button></div></section><section class="pos-card checkout-card"><h2>💳 Checkout</h2><div><div class="field-label">Customer</div><select id="customer"><option value="">Walk-in Customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e2($c['name'])?><?= $c['phone']?' — '.e2($c['phone']):'' ?></option><?php endforeach;?></select></div><div><div class="field-label">Discount</div><input id="saleDiscount" type="number" min="0" step="0.01" value="0"></div><div class="summary"><div><span>Subtotal</span><b>Rs. <span id="subtotal">0.00</span></b></div><div><span>Discount</span><b>Rs. <span id="discount">0.00</span></b></div><div class="grand"><span>TOTAL</span><strong>Rs. <span id="total">0.00</span></strong></div></div><div><div class="field-label">Payment</div><div class="pay-buttons"><button id="cash" onclick="setPayment('cash')">💵 CASH<br>F8</button><button id="card" onclick="setPayment('card')">💳 CARD<br>F9</button><button id="credit" onclick="setPayment('credit')">👤 CREDIT<br>F10</button></div></div><div id="creditWrap" style="display:none"><div class="field-label">Credit Customer</div><select id="creditCustomer"><option value="">Select customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e2($c['name'])?><?= $c['phone']?' — '.e2($c['phone']):'' ?></option><?php endforeach;?></select></div><div><div class="field-label">Received</div><input id="paid" type="number" min="0" step="0.01" placeholder="Amount received"></div><div id="change"></div><button class="btn complete" onclick="checkout()">💰 COMPLETE SALE <span class="shortcut">F12 / Ctrl+Enter</span></button><div class="shortcuts">F2 Search · F3 Customer · F4 Discount · F6 Hold · F7 Resume · F8 Cash · F9 Card · F10 Credit</div></section></div><div class="shortcuts">Scan barcode → choose Box / Strip / Tablet → sale stays on one screen · No page scrolling</div></main><div id="qtyModal" class="modal-back"><div class="modal"><h3 id="modalTitle">Add Medicine</h3><p id="modalInfo"></p><div class="row"><label><div class="field-label">Boxes</div><input id="mbox" type="number" min="0" step="1" value="0"></label><label><div class="field-label">Strips</div><input id="mstrip" type="number" min="0" step="1" value="0"></label><label><div class="field-label">Tablets</div><input id="mtab" type="number" min="0" step="1" value="1"></label></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="btn" onclick="addModal()">Add to Sale</button></div></div></div><script>const medicines=<?=json_encode($meds,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const saleToken=<?=json_encode($saleToken)?>;let cart=[];let payment='cash';let modalMed=null;let held=[];const $=id=>document.getElementById(id);const fmt=n=>Number(n).toFixed(2);function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}function units(m){return Math.max(1,(Number(m.units_per_strip)||1)*(Number(m.strips_per_box)||1))}function breakdown(m,q){q=Math.max(0,Math.floor(Number(q)||0));const u=Math.max(1,Number(m.units_per_strip)||1),box=units(m),b=Math.floor(q/box);q%=box;const s=Math.floor(q/u),t=q%u;return {boxes:b,strips:s,tablets:t}}function cartQty(id){const x=cart.find(v=>v.id===Number(id));return x?x.qty:0}function canAdd(m,q){const stock=Math.max(0,Number(m.stock)||0);return Number(q)>0&&cartQty(m.id)+Number(q)<=stock}function openQty(m){if(!m||Number(m.stock)<1)return alert('No stock available.');modalMed=m;$('modalTitle').textContent=m.name;$('modalInfo').textContent='Available: '+Number(m.stock)+' tablets · 1 box = '+units(m)+' tablets · 1 strip = '+(Number(m.units_per_strip)||1)+' tablets';$('mbox').value=0;$('mstrip').value=0;$('mtab').value=1;$('qtyModal').style.display='flex';$('mtab').focus()}function closeModal(){$('qtyModal').style.display='none';modalMed=null;$('search').focus()}function addModal(){if(!modalMed)return;const b=Math.max(0,parseInt($('mbox').value,10)||0),s=Math.max(0,parseInt($('mstrip').value,10)||0),t=Math.max(0,parseInt($('mtab').value,10)||0),u=Math.max(1,Number(modalMed.units_per_strip)||1),box=units(modalMed),qty=b*box+s*u+t;if(qty<1)return alert('Enter a quantity.');if(!canAdd(modalMed,qty))return alert('Not enough stock for this sale.');let x=cart.find(v=>v.id===Number(modalMed.id));if(!x){x={id:Number(modalMed.id),name:modalMed.name,qty:0,boxes:0,strips:0,tablets:0,stock:Number(modalMed.stock),price:Number(modalMed.retail_unit_price)||0,cost:Number(modalMed.purchase_price)||0,unitsPerStrip:u,boxUnits:box,discount:0};cart.push(x)}x.qty+=qty;x.boxes+=b;x.strips+=s;x.tablets+=t;closeModal();renderCart()}function renderResults(){const q=$('search').value.trim().toLowerCase();const rs=medicines.filter(m=>(m.name+' '+(m.generic_name||'')+' '+(m.strength||'')+' '+(m.barcode||'')).toLowerCase().includes(q)).slice(0,30);$('results').innerHTML=rs.map(m=>`<div class="result"><div><b>${esc(m.name)}</b><small>${esc((m.generic_name||'')+' '+(m.strength||''))} · Stock ${Number(m.stock)} · Rs.${fmt(m.retail_unit_price)}/tab${m.barcode?' · '+esc(m.barcode):''}</small></div><div class="sell-buttons"><button class="btn mini" onclick="openQty(medicines.find(x=>x.id==${Number(m.id)}))">ADD</button><button class="mini" onclick="addOne(${Number(m.id)},'box')">BOX</button><button class="mini" onclick="addOne(${Number(m.id)},'strip')">STRIP</button><button class="mini" onclick="addOne(${Number(m.id)},'tab')">TAB</button></div></div>`).join('')||'<div class="empty"><b>No medicine found</b><small>Try another name or barcode.</small></div>'}function addOne(id,type){const m=medicines.find(x=>Number(x.id)===Number(id));if(!m)return;const u=Math.max(1,Number(m.units_per_strip)||1),box=units(m),q=type==='box'?box:type==='strip'?u:1;if(!canAdd(m,q))return alert('Not enough stock for this sale.');let x=cart.find(v=>v.id===Number(id));if(!x){x={id:Number(id),name:m.name,qty:0,boxes:0,strips:0,tablets:0,stock:Number(m.stock),price:Number(m.retail_unit_price)||0,cost:Number(m.purchase_price)||0,unitsPerStrip:u,boxUnits:box,discount:0};cart.push(x)}x.qty+=q;if(type==='box')x.boxes++;if(type==='strip')x.strips++;if(type==='tab')x.tablets++;renderCart()}function removeItem(i){cart.splice(i,1);renderCart()}function editQty(i,v){const x=cart[i];if(!x)return;const q=Math.floor(Number(v));if(!Number.isFinite(q)||q<1)return renderCart();if(q>x.stock)return alert('Not enough stock.');x.qty=q;const b=breakdown(x,q);x.boxes=b.boxes;x.strips=b.strips;x.tablets=b.tablets;renderCart()}function editDiscount(i,v){const n=Number(v);cart[i].discount=Number.isFinite(n)?Math.max(0,n):0;renderCart()}function totals(){const sub=cart.reduce((a,x)=>a+x.qty*x.price,0);const itemDisc=cart.reduce((a,x)=>a+Math.min(x.qty*x.price,x.discount),0);const requested=Number($('saleDiscount').value);const saleDisc=Number.isFinite(requested)?Math.min(Math.max(0,requested),Math.max(0,sub-itemDisc)):0;return {sub,itemDisc,saleDisc,discount:itemDisc+saleDisc,total:Math.max(0,sub-itemDisc-saleDisc)}}function renderCart(){if(!cart.length)$('cart').innerHTML='<div class="empty"><b>No items in sale</b><small>Search a medicine or scan its barcode.</small></div>';else $('cart').innerHTML=cart.map((x,i)=>{const gross=x.qty*x.price,disc=Math.min(gross,x.discount),total=gross-disc;const q=x.boxes+'B '+x.strips+'S '+x.tablets+'T';return `<div class="cartrow"><div class="cart-main"><div><b>${esc(x.name)}</b><small>${q} · ${x.qty} tablets · Rs.${fmt(x.price)}/tablet</small></div><input type="number" min="1" max="${x.stock}" value="${x.qty}" onchange="editQty(${i},this.value)"><b>Rs. ${fmt(total)}</b><button class="remove" onclick="removeItem(${i})">×</button></div><div class="item-actions"><span style="font-size:9px;color:#64748b">Discount Rs.</span><input type="number" min="0" step="0.01" value="${fmt(x.discount)}" onchange="editDiscount(${i},this.value)"><span style="font-size:9px;color:#64748b">Cost Rs.${fmt(x.cost)}</span></div></div>`}).join('');const t=totals();$('count').textContent=cart.reduce((a,x)=>a+x.qty,0)+' tablets';$('subtotal').textContent=fmt(t.sub);$('discount').textContent=fmt(t.discount);$('total').textContent=fmt(t.total);preview()}function setPayment(p){payment=p;['cash','card','credit'].forEach(x=>$(x).classList.toggle('active',x===p));$('creditWrap').style.display=p==='credit'?'block':'none';if(p==='card'&&$('paid').value==='')$('paid').value=fmt(totals().total);if(p==='cash'&&$('paid').value==='')$('paid').value=fmt(totals().total);if(p==='credit')$('paid').value='';preview()}function preview(){const t=totals().total,p=$('paid').value===''?0:Number($('paid').value);if(!Number.isFinite(p)||p<0){$('change').innerHTML='<div class="due">Enter a valid received amount.</div>';return}if(payment==='cash'&&p>t)$('change').innerHTML='<div class="change">Change: Rs. '+fmt(p-t)+'</div>';else if(payment==='credit'&&p<t)$('change').innerHTML='<div class="due">Customer due: Rs. '+fmt(t-p)+'</div>';else $('change').innerHTML=''}function clearCart(){cart=[];$('paid').value='';$('saleDiscount').value='0';setPayment('cash');renderCart();$('search').focus()}function holdSale(){if(!cart.length)return alert('Cart is empty.');held.push({cart:JSON.parse(JSON.stringify(cart)),customer:$('customer').value,creditCustomer:$('creditCustomer').value,discount:$('saleDiscount').value,payment,paid:$('paid').value});clearCart();alert('Sale held as #'+held.length)}function resumeSale(){if(!held.length)return alert('No held sales.');const h=held.pop();cart=h.cart;$('customer').value=h.customer;$('creditCustomer').value=h.creditCustomer;$('saleDiscount').value=h.discount;$('paid').value=h.paid;setPayment(h.payment);renderCart()}function checkout(){if(!cart.length)return alert('Cart is empty.');const t=totals(),customer=payment==='credit'?$('creditCustomer').value:$('customer').value;if(payment==='credit'&&!customer)return alert('Select a customer for credit sale.');if(!Number.isFinite(t.total)||t.total<0)return alert('Invalid sale total.');const paidRaw=$('paid').value;const paid=paidRaw===''?(payment==='credit'?0:t.total):Number(paidRaw);if(!Number.isFinite(paid)||paid<0)return alert('Enter a valid received amount.');if(paid>t.total)return alert('Amount received cannot exceed total.');if(payment!=='credit'&&paid<t.total)return alert('Received amount must cover total.');const items=cart.map(x=>({id:x.id,qty:x.qty}));const f=document.createElement('form');f.method='post';f.action='index.php?action=sale';[['items',JSON.stringify(items)],['discount',t.discount],['payment_method',payment],['paid',paid],['customer_id',customer],['csrf_token',<?=json_encode(csrf_token())?>],['sale_token',saleToken]].forEach(([n,v])=>{const i=document.createElement('input');i.type='hidden';i.name=n;i.value=v;f.appendChild(i)});document.body.appendChild(f);f.submit()}function quickRender(){$('quickMeds').innerHTML=medicines.slice(0,7).map(m=>`<button onclick="addOne(${Number(m.id)},'tab')">${esc(m.name)}</button>`).join('')}$('search').addEventListener('input',renderResults);$('paid').addEventListener('input',preview);$('saleDiscount').addEventListener('input',renderCart);document.addEventListener('keydown',e=>{if(e.key==='F2'){e.preventDefault();$('search').focus();$('search').select()}else if(e.key==='F3'){e.preventDefault();$('customer').focus()}else if(e.key==='F4'){e.preventDefault();$('saleDiscount').focus();$('saleDiscount').select()}else if(e.key==='F6'){e.preventDefault();holdSale()}else if(e.key==='F7'){e.preventDefault();resumeSale()}else if(e.key==='F8'){e.preventDefault();setPayment('cash');$('paid').focus()}else if(e.key==='F9'){e.preventDefault();setPayment('card');$('paid').focus()}else if(e.key==='F10'){e.preventDefault();setPayment('credit');$('creditCustomer').focus()}else if(e.key==='F12'||(e.ctrlKey&&e.key==='Enter')){e.preventDefault();checkout()}else if(e.key==='Escape'&&$('qtyModal').style.display==='flex'){closeModal()}else if(e.ctrlKey&&e.key==='Backspace'){e.preventDefault();clearCart()}});document.addEventListener('click',e=>{if(e.target.id==='qtyModal')closeModal()});renderResults();renderCart();quickRender();setPayment('cash');</script></body></html>